@layer components {
  .feed-page {
    display: flex;
    justify-content: center;
    padding: var(--shelf-space-md);
  }

  .feed-page-wrapper {
    width: 100%;
    max-width: 960px;
  }

  .feed-page-heading {
    font-size: var(--shelf-font-size-xl);
    font-weight: var(--shelf-font-weight-bold);
    color: var(--shelf-color-text-primary);
    margin-bottom: var(--shelf-space-lg);
  }

  .feed-list {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
  }

  .feed-item {
    background: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    box-shadow: var(--shelf-shadow-sm);
  }

  .feed-item-title {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-color-text-primary);
    margin-bottom: var(--shelf-space-xs);
  }

  .feed-item-description {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
  }
}

NOM-02.code:
@layer components {
  .project-grid {
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--shelf-project-grid-column-min, 240px), 1fr));
    gap: var(--shelf-space-md);
  }

  .project-card {
    background: var(--shelf-color-surface);
    border: 1px solid var(--shelf-color-border);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-sm);
  }

  .project-card-name {
    color: var(--shelf-color-text-primary);
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    margin: 0;
  }

  .project-card-description {
    color: var(--shelf-color-text-secondary);
    font-size: var(--shelf-font-size-sm);
    margin: 0;
  }
}

NOM-C1.code:
@layer components {
  .card-footer {
    display: flex;
    align-items: center;
    gap: var(--shelf-space-xs);
  }

  .card-footer-timestamp {
    font-size: var(--shelf-font-size-xs);
    color: var(--shelf-fgColor-muted);
  }

  .card-footer-action {
    margin-inline-start: auto;
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-medium);
    color: var(--shelf-fgColor-accent);
    background: transparent;
    border: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-default);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-xs) var(--shelf-space-sm);
    cursor: pointer;
    transition: background-color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter),
      color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter);
  }

  .card-footer-action:hover {
    background: var(--shelf-bgColor-accent-hover);
    color: var(--shelf-fgColor-on-accent);
  }

  .card-footer-action:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .card-footer-action:active {
    background: var(--shelf-bgColor-accent-active);
    color: var(--shelf-fgColor-on-accent);
  }

  .card-footer-action:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}
